                    } else {
                        assert!(mounted.acknowledge_result_page(receipt.token).unwrap());
                    }
                }
                app.publish_mounted_typed_operation_unit(&mut mounted).await.unwrap();
                let final_page = if delayed_ack {
                    let presented = mounted.take_result_page().unwrap();
