                    PluginCloseStep::Blocked { reason } => panic!("full-map retained admission blocked: {reason}"),
                }
            }
            assert_eq!(result, Some(true), "completed target {index} must not consume permanent admission capacity");
            accepted += 1;
            for _ in 0..100_000 {
                if registry.can_begin() {
                    break;
                }
