        let source=MountedKernelMutationReceiptSource{document:ArtifactHandle(row["document"].as_u64().unwrap()as u128),mutation_id:row["mutationId"].as_str().unwrap(),invocation_id:row["invocationId"].as_str().unwrap(),schema:row["schema"].as_str().unwrap(),schema_separator:"",schema_suffix:"",author:row["author"].as_str().unwrap(),dependencies:&dependencies,inverse:&inverse,base_version:ArtifactVersion(row["baseVersion"].as_u64().unwrap()),timestamp:HybridLogicalTimestamp{actor:3,physical_ms:row["timestamp"].as_u64().unwrap(),logical:1},undo_policy:UndoPolicy::ExactBaseOnly};
